INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 30, 'theory', 'Quiz: An HTTP Server in Node.js');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 30, 0, 'What does the server return if the path exists but the method is not supported?', '["404 Not Found", "405 Method Not Allowed with an Allow header", "500 Internal Server Error", "200 OK with an empty body"]', 1, '405 says the path is known but the method does not fit; the Allow header lists the permitted methods. 404 means the path is unknown.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 30, 1, 'What is the right way to read the request body in Node.js?', '["Through req.body — it is already ready", "Collect chunks from the stream (data / for await), then join and parse them", "Only with synchronous fs.readFileSync", "The body cannot be read"]', 1, 'req is a readable stream: data arrives in pieces. We collect it, limit the size and only then parse.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 30, 2, 'What is the next function in middleware for?', '["Closes the server", "Passes control to the next handler in the chain", "Restarts the request", "Sends the response to the client"]', 1, 'Middleware either finishes the response or calls next(), passing the request further along the chain.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 30, 3, 'How do you protect against a request like GET /../../etc/passwd when serving static files?', '["Don''t: the browser will not send such a path", "Join the path with the root, normalize it and check that the result is inside the root", "Forbid all paths containing a dot", "Use only POST"]', 1, 'Normalization (path.resolve) plus a root prefix check rule out escaping the directory.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 30, 4, 'Why does a test start the server on port 0?', '["It is the default HTTP port", "The OS picks a free port — tests do not conflict with each other", "Port 0 is faster", "Port 0 turns the network off"]', 1, 'Port 0 asks the system to choose a free port; you read it from server.address() and use it in requests.');
